window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[227]={"id":"227","numero":227,"titre":"Insuffisance veineuse chronique. Varices","objectifs":[{"id":"227-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","contenu":"<div class=\"notion-course\"><p>L'<span>insuffisance veineuse chronique (IVC)</span> est une <strong>dysfonction du système veineux <span class=\"nc-yellow_bg\">profond</span> et/ou <span class=\"nc-yellow_bg\">superficiel</span></strong>. Elle résulte d'une <span><span class=\"nc-red_bg\">incontinence valvulaire</span></span>, avec ou sans oblitération veineuse associée, et touche préférentiellement les <strong><span class=\"nc-green nc-bold\">membres inférieurs</span></strong>.</p>\n      <p>Les <span>varices</span> sont une <strong><span class=\"nc-red_bg\">dilatation permanente et pathologique</span></strong> d'une ou plusieurs <span>veines superficielles</span> des <span class=\"nc-green nc-bold\">membres inférieurs</span>. Ce sont des veines dilatées et tortueuses (en orthostatisme, <span>diamètre</span> <span><span class=\"nc-pink_bg\">&gt; 3 mm</span></span>), sous-cutanées et visibles à l'inspection ; elles sont associées à un <span><span class=\"nc-blue_bg\">reflux</span></span> entraînant une stase du sang veineux.</p>\n      <div class=\"callout callout-warn\">⚠️ Piège : les <span class=\"nc-orange_bg\">varices</span> pathologiques sont à distinguer des « <span class=\"nc-orange_bg\">varices</span> du sportif », liées à une simple <span>lyse du tissu adipeux</span> et sans valeur pathologique.</div>\n      <p><strong>Rappel anatomique</strong> — le retour veineux du membre inférieur repose sur trois réseaux :</p>\n      <table>\n        <thead>\n          <tr><th>Réseau</th><th>Part du retour veineux</th><th>Constitution</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Réseau <span class=\"nc-yellow_bg\">profond</span></strong></td><td><span>90 %</span></td><td><strong>Proximal</strong> (sus-poplité) : veines poplitée, fémorale, iliaque, cave<br><strong>Distal</strong> (sous-poplité) : veines jambières et surales</td></tr>\n          <tr><td><strong>Réseau <span class=\"nc-yellow_bg\">superficiel</span></strong><br><em>(impliqué dans les varices)</em></td><td><span>10 %</span></td><td><span class=\"nc-pink_bg\">Grande veine saphène</span> (saphène interne) ; <span class=\"nc-pink_bg\">petite veine saphène</span> (saphène externe) ; reliées entre elles par des <span><span class=\"nc-pink nc-bold\">veines communicantes</span></span></td></tr>\n          <tr><td><strong><span class=\"nc-pink_bg\">Veines perforantes</span></strong></td><td>—</td><td>Relient le réseau <span class=\"nc-yellow_bg\">superficiel</span> au réseau <span class=\"nc-yellow_bg\">profond</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/anatomie-reseau-veineux-mi.png\" alt=\"Schéma anatomique du réseau veineux du membre inférieur : veine iliaque, fémorale, grande et petite veines saphènes, veines perforantes\" loading=\"lazy\">\n        <figcaption>Réseau veineux du membre inférieur : réseau profond (poplitée, fémorale, iliaque), réseau superficiel (grande et petite veines saphènes) et veines perforantes les reliant. Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <p><strong>📌 Classification <span>CEAP</span> (LiSA)</strong> — outil de référence pour parler le même langage devant une IVC. Combine 4 axes :</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>C — Clinique</strong> (grade 0-6, suffixe <em>a</em>=asymptomatique / <em>s</em>=symptomatique)</td><td>0 : aucun signe visible ou palpable · 1 : <span><span class=\"nc-yellow_bg\">télangiectasies</span> / <span class=\"nc-yellow_bg\">veines réticulaires</span></span> · 2 : <span>varices</span> · 3 : <span>œdème</span> · 4 : troubles trophiques (<span class=\"nc-brown_bg\">dermite ocre</span>, atrophie blanche, <span class=\"nc-brown_bg\">lipodermatosclérose</span>) · 5 : ulcère cicatrisé · 6 : <span>ulcère actif</span></td></tr>\n          <tr><td><strong>E — Étiologie</strong></td><td>Ec : congénitale · <strong>Ep : primitive</strong> (maladie variqueuse) · <strong>Es : secondaire</strong> (syndrome post-thrombotique)</td></tr>\n          <tr><td><strong>A — Anatomie</strong></td><td>As : <span class=\"nc-yellow_bg\">superficiel</span> · <strong>Ad : <span class=\"nc-yellow_bg\">profond</span></strong> (deep) · Ap : perforantes</td></tr>\n          <tr><td><strong>P — Physiopathologie</strong></td><td><strong>Pr : reflux</strong> · <strong>Po : obstruction</strong> · Pr,o : les deux</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">La <span class=\"nc-yellow_bg\">CEAP</span> <strong>n'est pas à apprendre par cœur</strong> mais LiSA en attend la compréhension : elle structure toute la démarche clinique de l'IVC (grade C dicte l'urgence de la prise en charge, E/P orientent l'étiologie et le mécanisme).</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"227-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes physiopathologiques responsables de l’IVC","contenu":"<div class=\"notion-course\"><p>Le <span>retour veineux</span> s'effectue contre la <span>pression orthostatique</span> (<span>pesanteur</span>), grâce à la synergie de plusieurs acteurs :</p>\n      <ul>\n        <li>Les valvules orientent le retour veineux et limitent le <span class=\"nc-blue_bg\">reflux</span> ; leur distribution varie selon les segments veineux.</li>\n        <li><strong>Pompe musculaire du <span class=\"nc-yellow_bg\">mollet</span></strong> (acteur majeur) : à la <strong>contraction</strong>, le muscle comprime le réseau <span class=\"nc-yellow_bg\">profond</span> contenu dans une <span>aponévrose inextensible</span> et propulse le flux vers le haut ; au <strong>relâchement</strong>, le sang du réseau <span class=\"nc-yellow_bg\">superficiel</span> est aspiré vers le réseau <span class=\"nc-yellow_bg\">profond</span>.</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Pression dynamique résiduelle</span></span></strong> : issue de l'éjection du ventricule gauche transmise jusqu'au versant veineux.</li>\n        <li>La pompe respiratoire contribue au retour veineux ; les variations thoraco-abdominales de pression s’associent à la pompe musculaire et aux valvules, sans se résumer à un retour uniquement pendant l’expiration.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/pompe-musculo-aponevrotique-mollet.png\" alt=\"Schéma de la pompe musculaire du mollet : au relâchement aspiration du sang, à la contraction compression du réseau veineux profond\" loading=\"lazy\">\n        <figcaption>Pompe musculaire du mollet : la contraction comprime le réseau veineux profond et propulse le sang vers le cœur ; le relâchement aspire le sang du réseau superficiel. Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <p>Tout dysfonctionnement de cette coopération crée une <strong>anomalie du retour veineux</strong>. Deux mécanismes principaux sont responsables de l'IVC :</p>\n      <ul>\n        <li><span>Reflux valvulaire</span> : incontinence des valvules anti-reflux.</li>\n        <li><span>Obstruction veineuse</span> : obstacle sur le trajet du retour veineux.</li>\n      </ul>\n      <p>Ces deux mécanismes aboutissent à une <span>hypertension veineuse</span>, qui conduit à une <span>souffrance microcirculatoire et tissulaire</span> — origine des <span>troubles trophiques</span> et de l'<span><span class=\"nc-red nc-bold\">ulcère veineux</span></span>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"227-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un syndrome post-thrombotique","contenu":"<div class=\"notion-course\"><ul><li>Le <span class=\"nc-orange_bg\">syndrome post-thrombotique</span> est une complication chronique d’une <span class=\"nc-red_bg\">TVP</span> : obstruction résiduelle et/ou reflux profond après lésions valvulaires, entraînant hypertension veineuse.</li><li>Il peut apparaître dans les mois suivant la TVP et se manifeste par douleur, lourdeur, œdème, troubles trophiques ou ulcère. La fréquence et la sévérité dépendent notamment de la localisation et des récidives.</li><li>Le diagnostic est clinique, après la phase aiguë, avec score de <span class=\"nc-yellow_bg\">Villalta</span> et Doppler selon le contexte. <span class=\"nc-yellow_bg\">Villalta</span> : 5–9 léger, 10–14 modéré, ≥ 15 ou <span class=\"nc-red nc-bold\">ulcère veineux</span> sévère ; l’ulcère n’est pas un simple point ajouté.</li><li>Prévention : anticoagulation correcte et prévention des récidives ; compression adaptée aux symptômes, sans promettre une réduction fixe de moitié chez tous.</li><li>Avant de traiter une varice secondaire, cartographier le réseau <span class=\"nc-yellow_bg\">profond</span> et les voies collatérales : ne pas supprimer une veine de suppléance utile. Toute intervention n’est pas absolument interdite pour tout antécédent de TVP.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"227-4","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies des varices et de l’IVC","contenu":"<div class=\"notion-course\"><p>Les étiologies des varices et de l'IVC se répartissent en trois grandes familles :</p>\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Insuffisance veineuse primitive</strong><br><em>(la plus fréquente)</em></td><td><span>Maladie variqueuse</span> (<span class=\"nc-orange_bg\">varices</span> essentielles), touchant les veines <strong>superficielles</strong> : <span class=\"nc-orange_bg\">varices</span> systématisées (aux dépens de la grande ou <span class=\"nc-pink_bg\">petite veine saphène</span>) ou non systématisées (« non-saphènes », perforantes ou pelviennes).<br>Plus rarement : <span>insuffisance valvulaire primitive profonde</span> (rare, voire exceptionnelle) → <span class=\"nc-blue_bg\">reflux</span> veineux <span class=\"nc-yellow_bg\">profond</span> — sujet <span class=\"nc-pink_bg\">jeune</span> : agénésie/dysgénésie valvulaire ; sujet <span class=\"nc-pink_bg\">âgé</span> : dégénérescence.</td></tr>\n          <tr><td><strong>Insuffisance veineuse secondaire</strong></td><td>Le syndrome post-thrombotique peut apparaître dans les mois ou années suivant la <span class=\"nc-red_bg\">TVP</span> ; il n’est pas limité à une apparition entre cinq et dix ans.</td></tr>\n          <tr><td><strong>Insuffisance veineuse fonctionnelle</strong></td><td>Retour veineux défaillant mais veines <strong>morphologiquement normales</strong> ; fréquente chez le sujet <span class=\"nc-pink_bg\">âgé</span> : <span>réduction de la marche</span> ; <span>altération de la dynamique cardio-respiratoire</span> (ex. <span>insuffisance cardiaque</span>) ; <span><span class=\"nc-orange_bg\">ankylose tibio-tarsienne</span></span> ; <span>perte de volume musculaire</span>.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span>Thrombose veineuse profonde</span> - EP</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"227-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les facteurs favorisant l’IVC","contenu":"<div class=\"notion-course\"><p>L'IVC et les varices partagent les mêmes <span>facteurs de risque</span> :</p>\n      <ul>\n        <li><span><span class=\"nc-brown_bg\">Hérédité</span></span> — facteur majeur.</li>\n        <li><span><span class=\"nc-brown_bg\">Âge</span></span> et <span>sexe <span class=\"nc-brown_bg\">féminin</span></span>.</li>\n        <li><span><span class=\"nc-brown_bg\">Grossesses multiples</span></span>.</li>\n        <li><span><span class=\"nc-brown_bg\">Sédentarité</span></span>, <span><span class=\"nc-brown_bg\">obésité</span></span> et <span><span class=\"nc-brown_bg\">surpoids</span></span>.</li>\n        <li><span><span class=\"nc-yellow_bg\">Constipation chronique</span></span>.</li>\n        <li><span class=\"nc-brown_bg\">Exposition à la </span><span><span class=\"nc-brown_bg\">chaleur</span></span>.</li>\n        <li><span>Orthostatisme prolongé</span> (station debout immobile).</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Piège classique : la <strong>marche prolongée n'est PAS un <span>facteur de risque</span></strong> d'IVC — c'est l'orthostatisme prolongé (station debout immobile) qui l'est. La marche active au contraire la pompe musculaire du mollet.</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"227-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l’IVC","contenu":"<div class=\"notion-course\"><p>L'IVC est un véritable <strong><span>problème de santé publique</span></strong> :</p>\n      <ul>\n        <li><span>Prévalence</span> globale d'environ <span><span class=\"nc-pink nc-bold\">30 à 60 %</span></span> dans les pays industrialisés.</li>\n        <li>Environ <span>20 millions</span> d'IVC et plus de <span>400 000</span> ulcères d'origine veineuse.</li>\n        <li>Nette <strong>prédominance <span class=\"nc-pink_bg\">féminine</span></strong> (<span>3 femmes pour 1 homme</span>), qui tend à s'équilibrer avec l'âge.</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"227-7","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier les varices et l’IVC","contenu":"<div class=\"notion-course\"><p><strong>Symptômes</strong> — fréquents, variés et peu spécifiques, leur intensité varie avec la stase veineuse :</p>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Lourdeurs</span></span> et <span><span class=\"nc-blue_bg\">pesanteurs</span></span> des <span class=\"nc-green nc-bold\">membres inférieurs</span>, <span><span class=\"nc-blue_bg\">crampes</span></span>, <span class=\"nc-blue_bg\">fatigabilité du mollet</span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Phlébalgie</span></span> : trajet veineux douloureux, <strong>sans induration</strong> (à la différence de la thrombose veineuse superficielle).</li>\n        <li><span><span class=\"nc-blue_bg\">Prurit</span></span> et gêne esthétique.</li>\n      </ul>\n      <p><strong>Symptômes moins connus</strong> :</p>\n      <ul>\n        <li><span><span class=\"nc-brown_bg\">Impatiences nocturnes</span></span> : peuvent s'intégrer dans le <span class=\"nc-orange nc-bold\">syndrome des jambes sans repos</span>.</li>\n        <li><span class=\"nc-brown_bg\">Brûlures, rougeur du pied</span> après quelques heures de <span class=\"nc-red nc-bold\">sommeil</span> ou en <span class=\"nc-red nc-bold\">déclivité</span>, soulagées par le froid.</li>\n        <li>Une obstruction veineuse proximale peut provoquer une claudication veineuse, parfois invalidante ; elle est améliorée par le <span class=\"nc-green_bg\">décubitus</span> et la surélévation, avec soulagement <span class=\"nc-red_bg\">souvent</span> plus lent qu’une claudication artérielle.</li>\n      </ul>\n      <table>\n        <thead>\n          <tr><th>Facteurs d'aggravation</th><th>Facteurs d'amélioration</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Station debout ou assise prolongée</span> ; <span class=\"nc-red_bg\">chaleur</span> ; <span><span class=\"nc-pink_bg\">grossesse</span></span> ; œstroprogestatifs ; période <span class=\"nc-pink_bg\">prémenstruelle</span></td><td><span class=\"nc-green_bg\">Froid</span> ; <span class=\"nc-green_bg\">surélévation des membres inférieurs</span> ; <span class=\"nc-green_bg\">décubitus</span> ; <span class=\"nc-green_bg\">exercice physique</span> ; compression veineuse élastique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes cutanés</strong> — du plus précoce au plus avancé :</p>\n      <table>\n        <thead>\n          <tr><th>Signe</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-yellow_bg\">Télangiectasies</span></span></td><td>Dilatations intradermiques de petit calibre (<span><span class=\"nc-pink nc-bold\">1 mm</span></span>)</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Veines réticulaires</span></span></td><td>Dilatations sous-dermiques ramifiées (<span>1 à 3 mm</span>) ; au niveau de la <span class=\"nc-blue_bg\">cheville</span> ou de l'<span class=\"nc-blue_bg\">arche plantaire</span>, elles forment la <span><span class=\"nc-red_bg\">corona</span> phlebectatica</span> (<span class=\"nc-blue_bg\">couronne phlébectasique</span>), <strong>signe précurseur d'<span><span class=\"nc-red nc-bold\">ulcère veineux</span></span></strong></td></tr>\n          <tr><td><span>Varices</span></td><td>Veines variqueuses sous-cutanées (<span><span class=\"nc-pink_bg\">&gt; 3 mm</span></span>)</td></tr>\n          <tr><td><span>Œdème</span></td><td>Blanc, mou, prend le godet, avec nette <strong><span class=\"nc-red nc-bold\">recrudescence vespérale</span></strong></td></tr>\n          <tr><td>Troubles trophiques</td><td><span><span class=\"nc-brown_bg\">Eczéma variqueux</span></span> ; <span><span class=\"nc-brown_bg\">dermite ocre</span></span> ; <span>atrophie blanche de Milian</span> (petites zones <span class=\"nc-red_bg nc-bold\">blanc</span> <span class=\"nc-red_bg\">porcelaine</span> malléolaires, ischémie cutanée annonçant l'ulcère) ; <span>hypodermite / <span class=\"nc-brown_bg\">lipodermatosclérose</span></span></td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Ulcère veineux</span></span></td><td><span>Stade</span> ultime de l'IVC</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/varices-saphene-interne.png\" alt=\"Photographie clinique de varices : veines variqueuses dilatées et tortueuses sur la jambe\" loading=\"lazy\">\n        <figcaption>Varices : veines superficielles dilatées, tortueuses et saillantes sur le membre inférieur. Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/veines-reticulaires.png\" alt=\"Photographie clinique de veines réticulaires : dilatations veineuses sous-dermiques ramifiées de petit calibre\" loading=\"lazy\">\n        <figcaption>Veines réticulaires : dilatations veineuses sous-dermiques ramifiées de petit calibre (<span>1 à 3 mm</span>). Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <p><strong>Examen clinique</strong> : bilatéral et comparatif, patient en escabeau de phlébologie. Il associe l'<strong>inspection</strong> (varices, varicosités, complications cutanées), la <strong>palpation</strong> (<span class=\"nc-blue_bg\">phlébalgie</span>, recherche d'induration évoquant une thrombose) et l'<strong>auscultation</strong> (un <span class=\"nc-brown_bg\">souffle évoque une </span><span><span class=\"nc-brown_bg\">fistule</span></span><span class=\"nc-brown_bg\"> artério-veineuse</span>). Les manœuvres cliniques (signe du flot, signe de <span class=\"nc-yellow_bg\">Schwartz</span>, épreuve de <span class=\"nc-yellow_bg\">Trendelenburg</span>) sont <strong>hors programme</strong>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 350 — Grosse jambe rouge aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"227-8","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître un ulcère variqueux","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-red nc-bold\">ulcère veineux</span></span> (ou ulcère variqueux) est le plus fréquent des ulcères de jambe — il en représente <span>80 %</span>. La distinction avec l'<span>ulcère artériel</span> est un point clé du raisonnement diagnostique :</p>\n      <table>\n        <thead>\n          <tr><th>Critère</th><th><span><span class=\"nc-red nc-bold\">Ulcère veineux</span></span></th><th><span>Ulcère artériel</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Terrain</span></td><td>Femme <span>&gt; 50 ans</span> (≈ <span>1,5 F / 1 H</span>) ; ATCD de <span>TVP</span>, varices, <span><span class=\"nc-brown_bg\">surpoids</span></span></td><td>Homme <span>&gt; 50 ans</span> ; <span>FDR cardiovasculaires</span> ; ATCD de <span>claudication</span> intermittente</td></tr>\n          <tr><td>Localisation</td><td><strong><span class=\"nc-yellow_bg\">Péri-malléolaire</span></strong>, jusqu'au 1/3 inférieur du mollet ; <strong>bord <span class=\"nc-green nc-bold\">régulier</span></strong></td><td>Zones d'appui et de frottement (<span class=\"nc-yellow_bg\">pied</span> : orteils, dos et bord externe, talon) ; parfois face antérieure (ulcère « suspendu »)</td></tr>\n          <tr><td>Taille</td><td><span class=\"nc-red_bg\">Souvent</span> <span class=\"nc-red_bg\">étendu</span>, parfois circonférentiel</td><td><span class=\"nc-green_bg\">Petite</span> taille</td></tr>\n          <tr><td>Douleur</td><td>Peu ou pas <span class=\"nc-red_bg\">douloureux</span></td><td><span><span class=\"nc-red_bg\">Douloureux</span></span>, habituellement intense</td></tr>\n          <tr><td>Profondeur</td><td><span class=\"nc-green_bg\">Superficiel</span>, <span class=\"nc-green_bg\">non creusant</span></td><td><span><span class=\"nc-red_bg\">Creusant</span></span>, risque d'exposition articulaire / tendineuse / osseuse</td></tr>\n          <tr><td>Fond</td><td>Exsudatif, fibrineux</td><td>Atone, pâle</td></tr>\n          <tr><td>Peau péri-ulcéreuse</td><td>Varices, <span class=\"nc-yellow_bg\">télangiectasies</span>, <span><span class=\"nc-brown_bg\">eczéma variqueux</span></span>, <span><span class=\"nc-brown_bg\">dermite ocre</span></span>, atrophie blanche, <span><span class=\"nc-red_bg\">corona</span> phlebectatica</span> ; examen artériel normal</td><td>Peau luisante, <span class=\"nc-green\">dépilée</span> ; <span class=\"nc-blue nc-bold\">baisse de la température cutanée</span> ; <span>abolition des <span class=\"nc-blue nc-bold\">pouls périphériques</span></span></td></tr>\n          <tr><td><span>IPS</span></td><td>Normal : <span>0,9 à 1,3</span> (<span><span class=\"nc-red nc-bold\">ulcère veineux</span></span> pur)</td><td><span>&lt; 0,9</span> ; entre <span>0,7 et 0,9</span> = <span class=\"nc-yellow_bg\">ulcère mixte à prédominance veineuse</span> ; <span>&gt; 1,3</span> = artères calcifiées</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Devant tout ulcère de <span class=\"nc-blue nc-bold\">jambe</span>, la mesure de l'<span>IPS</span> est systématique : elle conditionne la possibilité d'une compression élastique (<span>contre-indiquée</span> si artériopathie sévère).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 228 — Ulcère de la jambe · 225 — Artériopathie oblitérante - anévrysme</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"227-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les méthodes diagnostiques de l’IVC","contenu":"<div class=\"notion-course\"><p>L'<span>échographie-Doppler veineuse des <span class=\"nc-green nc-bold\">membres inférieurs</span></span>, réalisée en <strong><span>position debout</span></strong>, est l'<strong><span>examen de référence</span></strong> du diagnostic d'IVC.</p>\n      <p><strong>Indications</strong> :</p>\n      <ul>\n        <li>Confirmer le diagnostic d'IVC.</li>\n        <li>Bilan <strong>pré-opératoire</strong> (systématique avant <span>chirurgie variqueuse</span>).</li>\n        <li>Bilan <strong>pré-sclérose</strong> : <span>cartographie veineuse</span> et mesure du <span>diamètre</span> des varices.</li>\n        <li>Bilan d'un <span>ulcère</span> des <span class=\"nc-green nc-bold\">membres inférieurs</span>.</li>\n        <li>Suspicion de <span>TVP</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">Les manœuvres cliniques (signe du flot, signe de <span class=\"nc-yellow_bg\">Schwartz</span>, épreuve de <span class=\"nc-yellow_bg\">Trendelenburg</span>) sont <strong>hors programme</strong> de l'EDN.</div><h4>Points de raisonnement et précautions</h4><ul><li>Le Doppler de <span class=\"nc-blue_bg\">reflux</span> est réalisé en orthostatisme ou position adaptée ; la recherche de <span class=\"nc-red_bg\">TVP</span> aiguë suit un protocole de compression différent. Une grosse <span class=\"nc-blue nc-bold\">jambe</span> brutale ne doit pas être attribuée d’emblée à l’insuffisance veineuse chronique.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"227-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge thérapeutiques de l’IVC","contenu":"<div class=\"notion-course\"><p><strong>1. Mesures générales et hygiène de vie</strong> — socle du traitement :</p>\n      <ul>\n        <li>Surélévation des jambes et des pieds de <span>7 à 10 cm</span> au-dessus du lit.</li>\n        <li>Lutte contre le <span><span class=\"nc-brown_bg\">surpoids</span></span> et la <span><span class=\"nc-brown_bg\">sédentarité</span></span> (<span><span class=\"nc-green_bg\">marche régulière quotidienne</span></span>).</li>\n        <li>Éviter de croiser les jambes en position assise et les stations debout immobiles prolongées.</li>\n        <li>Éviter le chauffage par le sol, les bains chauds et l'exposition prolongée au soleil.</li>\n        <li><span class=\"nc-green_bg\">Prise en charge de la </span><span><span class=\"nc-green_bg\">constipation</span></span>.</li>\n      </ul>\n      <p><strong>2. Compression élastique</strong> — action hémodynamique et microcirculatoire, avec une pression dégressive de la <span class=\"nc-blue_bg\">cheville</span> vers la cuisse. Pose le <strong>matin</strong>, dans l'heure suivant le lever. Quatre classes selon la pression exercée à la <span class=\"nc-blue_bg\">cheville</span> :</p>\n      <table>\n        <thead>\n          <tr><th>Classe</th><th>Pression</th><th>Indications principales</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Classe 1</span></td><td><span>10 à 15 mmHg</span></td><td>Prévention de la <span>TVP</span> ; IVC fonctionnelle</td></tr>\n          <tr><td><span>Classe 2</span></td><td><span>15,1 à 20 mmHg</span></td><td><span class=\"nc-orange_bg\">Varices</span> ; <span><span class=\"nc-red_bg\">TVP</span></span> ; post-opératoire de <span>chirurgie variqueuse</span></td></tr>\n          <tr><td><span>Classe 3</span></td><td><span>20,1 à 36 mmHg</span></td><td>SPT ; <span>œdème</span> veineux chronique ; <span>troubles trophiques</span> ; ulcère cicatrisé</td></tr>\n          <tr><td><span>Classe 4</span></td><td><span>&gt; 36 mmHg</span></td><td><span class=\"nc-orange_bg\">Insuffisance lymphatique</span> ; <span><span class=\"nc-red nc-bold\">ulcère veineux</span></span> cicatrisé ou ouvert</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <strong><span>Contre-indications</span> de la compression élastique</strong> : <span>artériopathie oblitérante avec <span class=\"nc-red nc-bold\">IPS &lt; 0,6</span></span> ; <span><span class=\"nc-red_bg\">thrombose veineuse septique</span></span> ; <span>phlegmatia caerulea</span> (phlébite bleue) ; <span><span class=\"nc-red_bg\">microangiopathie diabétique</span> avec <span class=\"nc-red nc-bold\">TcPO2 &lt; 30 mmHg</span></span>.</div>\n      <p><strong>3. Traitement <span>médicamenteux</span></strong> : les <span><span class=\"nc-pink_bg\">veinotropes</span></span> (veinotoniques, veino-actifs) ont un <strong>effet faible</strong>. Ils ne sont indiqués qu'en cas de gêne fonctionnelle, <strong>à titre <span class=\"nc-yellow_bg\">adjuvant</span></strong> de l'hygiène de vie et de la compression, en cures séquentielles courtes.</p>\n      <p><strong>4. Destruction des veines pathologiques</strong> — indiquée en cas de <span>varices</span> :</p>\n      <ul>\n        <li><strong>Traitements endovasculaires</strong> : <span><span class=\"nc-pink_bg\">sclérothérapie</span></span> (injection d'un produit sclérosant) ; <span>techniques thermiques endoveineuses</span> (<span><span class=\"nc-pink_bg\">laser</span></span>, <span class=\"nc-pink_bg\">radiofréquence</span>) — <strong>traitement de 1ʳᵉ intention</strong> <span class=\"nc-yellow_bg\">en l'absence d'indication de sclérothérapie</span>.</li>\n        <li><strong>Traitement chirurgical</strong> (indications de plus en plus réduites) : <span><span class=\"nc-pink_bg\">éveinage par stripping</span></span> ; <span><span class=\"nc-pink_bg\">phlébectomies</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Piège : les <strong><span class=\"nc-orange_bg\">varices</span> secondaires à un SPT doivent habituellement être respectées</strong> — elles suppléent l'obstruction veineuse profonde. De même, chez un patient avec FDR cardiovasculaires ou maladie athéromateuse, rester conservateur sur les troncs saphènes (réserve possible pour un <span>pontage</span> artériel ultérieur).</div>\n      <p><strong>Cas particulier</strong> — en cas d'<span><span class=\"nc-brown_bg\">eczéma variqueux</span></span> : <span><span class=\"nc-pink_bg\">dermocorticoïdes</span></span> + <span><span class=\"nc-pink_bg\">émollients</span></span>, en plus des mesures précédentes.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 222 — FDR cardiovasculaire</em></p><h4>Points de raisonnement et précautions</h4><ul><li>Avant compression, évaluer les pouls et l’IPS si risque artériel ; pression d’orteil si IPS non interprétable. Choisir la pression réellement délivrée, l’aptitude à enfiler le dispositif et le contrôle cutané. Ulcère actif : stratégie de compression et traitement du reflux en équipe spécialisée.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance veineuse chronique (227)</a></li><li><a href=\"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Collèges de médecine et chirurgie vasculaires · Référentiel 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Ulcère de jambe à prédominance veineuse</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":4}],"astuces":[{"type":"piege","titre":"Raisonner avant le chiffre","contenu":"<div class=\"notion-course\"><p>Interpréter un seuil avec le tableau clinique, le référentiel et les unités ; une complication aiguë impose de réévaluer immédiatement la stratégie.</p></div>"},{"type":"piege","titre":"Source et synthèse","contenu":"<div class=\"notion-course\"><p>Les schémas du collège restent accessibles. Les arbres ATLAS et leurs compléments sont explicitement identifiés et reliés aux objectifs concernés.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Rechercher les signes de gravité puis préciser la probabilité et le mécanisme.</li><li>Choisir les examens capables de modifier la décision et confronter les résultats à la clinique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Adapter la prise en charge à l’urgence, au terrain, aux contre-indications et aux préférences.</li><li>Prévoir surveillance, éducation et réévaluation ; utiliser les arbres reliés au cours.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://pufr-editions.fr/wp-content/uploads/2022/06/PUFR-ECN-VASCU-interieur-BD.pdf","label":"Collèges de médecine et chirurgie vasculaires · Référentiel 2022 ↗"},{"href":"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts","label":"HAS · Compression médicale dans les affections veineuses chroniques ↗"},{"href":"https://www.has-sante.fr/upload/docs/application/pdf/recommandations_finales_pdf.pdf","label":"HAS · Ulcère de jambe à prédominance veineuse ↗"}],"cards":[{"i":"105a44e1a771","n":227,"o":"227-1","u":"Définition","t":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","q":"Quelle est la définition de l'insuffisance veineuse chronique (IVC) ?","a":"<div class=\"notion-course\"><p>L'insuffisance veineuse chronique (IVC) est une <strong>dysfonction du système veineux <span class=\"nc-yellow_bg\">profond</span> et/ou <span class=\"nc-yellow_bg\">superficiel</span></strong>, préférentiellement des <span class=\"nc-green nc-bold\">membres inférieurs</span>. Elle est causée par une <strong><span class=\"nc-red_bg\">incontinence valvulaire</span></strong>, associée ou non à une oblitération veineuse.</p></div>"},{"i":"23a05fa3f654","n":227,"o":"227-1","u":"Définition","t":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","q":"Quel piège doit-on connaître concernant le diagnostic des varices ?","a":"<div class=\"notion-course\"><p>Chez le sportif maigre, des veines superficielles peuvent être très visibles sans <span class=\"nc-blue_bg\">reflux</span> pathologique ; la visibilité seule ne suffit pas à diagnostiquer une maladie variqueuse.</p></div>"},{"i":"8e92e6b88958","n":227,"o":"227-1","u":"Définition","t":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","q":"Qu'est-ce qu'une varice, et quelles sont ses caractéristiques observées à l'inspection ?","a":"<div class=\"notion-course\"><p>Une varice est une <strong><span class=\"nc-red_bg\">dilatation permanente et pathologique</span></strong> d'une ou plusieurs veines superficielles des <span class=\"nc-green nc-bold\">membres inférieurs</span>.</p><p>À l'inspection, elles apparaissent comme des veines <strong>dilatées et tortueuses</strong>, sous-cutanées et visibles, avec un diamètre <strong>supérieur à 3 mm en orthostatisme</strong>, et sont associées à un <span class=\"nc-blue_bg\">reflux</span> entraînant une stase du sang veineux.</p></div>"},{"i":"257e6a3a8cbf","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quels sont les signes cliniques recherchés pour le diagnostic positif du syndrome post-thrombotique ?","a":"<div class=\"notion-course\"><ul><li>Il peut apparaître dans les mois suivant la TVP et se manifeste par douleur, lourdeur, œdème, troubles trophiques ou ulcère. La fréquence et la sévérité dépendent notamment de la localisation et des récidives.</li><li>Le diagnostic est clinique, après la phase aiguë, avec score de <span class=\"nc-yellow_bg\">Villalta</span> et Doppler selon le contexte. <span class=\"nc-yellow_bg\">Villalta</span> : 5–9 léger, 10–14 modéré, ≥ 15 ou <span class=\"nc-red nc-bold\">ulcère veineux</span> sévère ; l’ulcère n’est pas un simple point ajouté.</li></ul></div>"},{"i":"754ae296b447","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quels sont les deux mécanismes physiopathologiques principaux du syndrome post-thrombotique ?","a":"<div class=\"notion-course\"><ul><li>Le <span class=\"nc-orange_bg\">syndrome post-thrombotique</span> est une complication chronique d’une <span class=\"nc-red_bg\">TVP</span> : obstruction résiduelle et/ou reflux profond après lésions valvulaires, entraînant hypertension veineuse.</li></ul></div>"},{"i":"85b1ece8c47c","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Pourquoi faut-il cartographier les voies de suppléance avant de traiter une varice post-thrombotique ?","a":"<div class=\"notion-course\"><ul><li>Avant de traiter une varice secondaire, cartographier le réseau <span class=\"nc-yellow_bg\">profond</span> et les voies collatérales : ne pas supprimer une veine de suppléance utile. Toute intervention n’est pas absolument interdite pour tout antécédent de TVP.</li></ul></div>"},{"i":"b3756240a355","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quel rôle l'écho-Doppler veineux joue-t-il dans le diagnostic du syndrome post-thrombotique ?","a":"<div class=\"notion-course\"><ul><li>Le diagnostic est clinique, après la phase aiguë, avec score de <span class=\"nc-yellow_bg\">Villalta</span> et Doppler selon le contexte. <span class=\"nc-yellow_bg\">Villalta</span> : 5–9 léger, 10–14 modéré, ≥ 15 ou <span class=\"nc-red nc-bold\">ulcère veineux</span> sévère ; l’ulcère n’est pas un simple point ajouté.</li></ul></div>"},{"i":"bd1a26c4ae50","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quelle est la définition du syndrome post-thrombotique (SPT) ?","a":"<div class=\"notion-course\"><ul><li>Le <span class=\"nc-orange_bg\">syndrome post-thrombotique</span> est une complication chronique d’une <span class=\"nc-red_bg\">TVP</span> : obstruction résiduelle et/ou reflux profond après lésions valvulaires, entraînant hypertension veineuse.</li><li>Il peut apparaître dans les mois suivant la TVP et se manifeste par douleur, lourdeur, œdème, troubles trophiques ou ulcère. La fréquence et la sévérité dépendent notamment de la localisation et des récidives.</li></ul></div>"},{"i":"d1e52f99f2fd","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quelle est la prise en charge préventive du syndrome post-thrombotique ?","a":"<div class=\"notion-course\"><ul><li>Prévention : anticoagulation correcte et prévention des récidives ; compression adaptée aux symptômes, sans promettre une réduction fixe de moitié chez tous.</li></ul></div>"},{"i":"18325c2cc236","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Quels sont les facteurs favorisants comportementaux ou liés au mode de vie pour l'insuffisance veineuse chronique (IVC) et les varices ?","a":"<div class=\"notion-course\"><ul><li>La <strong>sédentarité</strong>.</li><li>L'<strong><span class=\"nc-brown_bg\">obésité</span></strong> et le <strong><span class=\"nc-brown_bg\">surpoids</span></strong>.</li><li>La <strong><span class=\"nc-yellow_bg\">constipation chronique</span></strong>.</li><li>L'<strong><span class=\"nc-brown_bg\">exposition à la chaleur</span></strong>.</li></ul></div>"},{"i":"226c83ea3d17","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Parmi l'orthostatisme prolongé et la marche prolongée, lequel est un facteur favorisant de l'insuffisance veineuse chronique (IVC) et des varices ?","a":"<div class=\"notion-course\"><p>L'<strong>orthostatisme prolongé</strong> (station debout immobile) est un facteur favorisant de l'insuffisance veineuse chronique (IVC) et des varices. La <strong>marche prolongée n'est PAS un facteur de risque</strong> car la marche active favorise la pompe musculaire du <span class=\"nc-red_bg\">mollet</span>.</p></div>"},{"i":"5016f311aa33","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Quels sont les facteurs favorisants liés aux spécificités démographiques ou physiologiques de l'insuffisance veineuse chronique (IVC) et des varices ?","a":"<div class=\"notion-course\"><ul><li>L'<strong>âge</strong>.</li><li>Le <strong>sexe <span class=\"nc-brown_bg\">féminin</span></strong>.</li><li>Les <strong><span class=\"nc-brown_bg\">grossesses multiples</span></strong>.</li></ul></div>"},{"i":"9f8d7c4bfd22","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Quel est le facteur favorisant le plus important pour l'insuffisance veineuse chronique (IVC) et les varices ?","a":"<div class=\"notion-course\"><p>Le facteur favorisant majeur de l'insuffisance veineuse chronique (IVC) et des varices est l'<strong><span class=\"nc-brown_bg\">hérédité</span></strong>.</p></div>"},{"i":"409c29750a45","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Comment les symptômes de l'insuffisance veineuse chronique (IVC) évoluent-ils en fonction de certains facteurs ?","a":"<div class=\"notion-course\"><p>Les symptômes de l'IVC sont :</p><ul><li>Aggravés par la <strong><span class=\"nc-red_bg\">station debout ou assise prolongée</span></strong>, la <strong><span class=\"nc-red_bg\">chaleur</span></strong>, la <strong><span class=\"nc-pink_bg\">grossesse</span></strong>, les <strong>œstroprogestatifs</strong>, la <strong>période <span class=\"nc-pink_bg\">prémenstruelle</span></strong>.</li><li>Améliorés par le <strong><span class=\"nc-green_bg\">froid</span></strong>, la <strong><span class=\"nc-green_bg\">surélévation des membres inférieurs</span></strong>, le <strong><span class=\"nc-green_bg\">décubitus</span></strong>, l'<strong><span class=\"nc-green_bg\">exercice physique</span></strong>, la <strong>compression veineuse élastique</strong>.</li></ul></div>"},{"i":"a2409dec991d","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Quels sont les signes cutanés de l'insuffisance veineuse chronique (IVC), du plus précoce au plus avancé ?","a":"<div class=\"notion-course\"><p>Les signes cutanés de l'IVC, du plus précoce au plus avancé, sont :</p><ul><li><strong><span class=\"nc-yellow_bg\">Télangiectasies</span></strong> (dilatations intradermiques &lt; <span class=\"nc-pink nc-bold\">1 mm</span>)</li><li><strong><span class=\"nc-yellow_bg\">Veines réticulaires</span></strong> (dilatations sous-dermiques ramifiées de 1 à 3 mm), pouvant former une <strong><span class=\"nc-red_bg\">corona</span> phlebectatica</strong> à la <span class=\"nc-blue_bg\">cheville</span>/<span class=\"nc-blue_bg\">arche plantaire</span>, signe précurseur d'ulcère.</li><li><strong>Varices</strong> (veines superficielles dilatées, tortueuses et saillantes <span class=\"nc-pink_bg\">&gt; 3 mm</span>).</li><li><strong>Œdème</strong> (blanc, mou, prend le godet, <span class=\"nc-red nc-bold\">recrudescence vespérale</span>).</li><li><strong>Troubles trophiques</strong> : <ul><li><strong><span class=\"nc-brown_bg\">Eczéma variqueux</span></strong></li><li><strong><span class=\"nc-brown_bg\">Dermite ocre</span></strong></li><li><strong><span class=\"nc-brown_bg\">Atrophie blanche de Millian</span></strong></li><li><strong>Hypodermite / <span class=\"nc-brown_bg\">lipodermatosclérose</span></strong></li></ul></li><li><strong><span class=\"nc-red nc-bold\">Ulcère veineux</span></strong> (stade ultime de l'IVC).</li></ul></div>"},{"i":"a5327fd36d92","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Quels sont les symptômes fréquents et peu spécifiques de l'insuffisance veineuse chronique (IVC) qui varient avec la stase veineuse ?","a":"<div class=\"notion-course\"><p>Les symptômes fréquents de l'IVC sont :</p><ul><li><strong><span class=\"nc-blue_bg\">Lourdeurs</span> et <span class=\"nc-blue_bg\">pesanteurs</span> des <span class=\"nc-green nc-bold\">membres inférieurs</span></strong></li><li><strong><span class=\"nc-blue_bg\">Crampes</span></strong></li><li><strong><span class=\"nc-blue_bg\">Fatigabilité du mollet</span></strong></li><li><strong><span class=\"nc-blue_bg\">Phlébalgie</span></strong> (trajet veineux douloureux sans induration)</li><li><strong><span class=\"nc-blue_bg\">Prurit</span> et gêne esthétique</strong></li><li><strong><span class=\"nc-brown_bg\">Impatiences nocturnes</span></strong></li><li><strong><span class=\"nc-brown_bg\">Brûlures, rougeur du pied</span></strong> après quelques heures de <span class=\"nc-red nc-bold\">sommeil</span> ou en <span class=\"nc-red nc-bold\">déclivité</span>, soulagées par le froid</li><li>Une obstruction veineuse proximale peut provoquer une claudication veineuse, parfois invalidante ; elle est améliorée par le <span class=\"nc-green_bg\">décubitus</span> et la surélévation, avec soulagement <span class=\"nc-red_bg\">souvent</span> plus lent qu’une claudication artérielle.</li></ul></div>"},{"i":"ba5834c8c391","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Quel est l'examen clinique à réaliser pour un patient suspecté d'insuffisance veineuse chronique (IVC) et de varices ?","a":"<div class=\"notion-course\"><p>L'examen clinique doit être réalisé en <strong>position debout sur un escabeau de phlébologie</strong>, il est <strong>bilatéral et comparatif</strong> et comprend :</p><ul><li>L'<strong>inspection</strong> : recherche de varices, varicosités, complications cutanées.</li><li>La <strong>palpation</strong> : recherche de <span class=\"nc-blue_bg\">phlébalgie</span>, d'induration (évoquant une thrombose).</li><li>L'<strong>auscultation</strong> : recherche d'un souffle (évoquant une fistule artério-veineuse).</li></ul><p>Les manœuvres cliniques (signe du flot, signe de <span class=\"nc-yellow_bg\">Schwartz</span>, épreuve de <span class=\"nc-yellow_bg\">Trendelenburg</span>) sont hors programme de l'EDN.</p></div>"},{"i":"5779b3deb22a","n":227,"o":"227-8","u":"Diagnostic positif","t":"Savoir reconnaître un ulcère variqueux","q":"Quels sont les principaux critères cliniques permettant de distinguer un ulcère variqueux d'un ulcère artériel ?","a":"<div class=\"notion-course\"><ul><li><strong>Terrain :</strong> L'ulcère variqueux touche préférentiellement la <strong>femme de plus de 50 ans</strong>, avec des antécédents de <strong><span class=\"nc-red_bg\">TVP</span></strong>, de <strong>varices</strong> ou de <strong><span class=\"nc-brown_bg\">surpoids</span></strong>.</li><li><strong>Localisation :</strong> Il est typiquement <strong><span class=\"nc-yellow_bg\">péri-malléolaire</span></strong>, jusqu'au 1/3 inférieur du mollet, avec des <strong>bords réguliers</strong>.</li><li><strong>Douleur :</strong> Il est généralement <strong>peu ou pas douloureux</strong>.</li><li><strong>Profondeur :</strong> Il est <strong><span class=\"nc-green_bg\">superficiel</span></strong> et <span class=\"nc-green_bg\">non creusant</span>.</li><li><strong>Fond :</strong> Le fond est souvent <strong><span class=\"nc-blue_bg\">exsudatif</span> et <span class=\"nc-blue_bg\">fibrineux</span></strong>.</li><li><strong>Peau péri-ulcéreuse :</strong> Elle présente souvent des <strong>varices</strong>, des <strong><span class=\"nc-yellow_bg\">télangiectasies</span></strong>, un <strong><span class=\"nc-brown_bg\">eczéma variqueux</span></strong>, une <strong><span class=\"nc-brown_bg\">dermite ocre</span></strong>, une <strong>atrophie blanche</strong> ou une <strong><span class=\"nc-red_bg\">corona</span> phlébectatique</strong>, et l'examen artériel est normal.</li></ul></div>"},{"i":"d789864e18f3","n":227,"o":"227-8","u":"Diagnostic positif","t":"Savoir reconnaître un ulcère variqueux","q":"Quel est l'intérêt et la valeur de l'Index de Pression Systolique (IPS) pour le diagnostic étiologique des ulcères de jambe, notamment l'ulcère variqueux ?","a":"<div class=\"notion-course\"><p>L'<strong>IPS</strong> est une mesure <strong>systématique</strong> devant tout ulcère de jambe. Pour un ulcère variqueux pur, l'IPS est <strong>normal, entre 0,9 et 1,3</strong>. Un IPS <strong>inférieur à 0,9</strong> oriente vers un ulcère artériel, tandis qu'une valeur <strong>entre 0,7 et 0,9</strong> suggère un <span class=\"nc-yellow_bg\">ulcère mixte à prédominance veineuse</span>. Il est fondamental car il <strong>conditionne la possibilité d'une compression élastique</strong>, qui est contre-indiquée en cas d'artériopathie sévère (IPS bas).</p></div>"},{"i":"d7c648a24f64","n":227,"o":"227-8","u":"Diagnostic positif","t":"Savoir reconnaître un ulcère variqueux","q":"Comment définir et caractériser l'ulcère variqueux par rapport aux autres ulcères de jambe ?","a":"<div class=\"notion-course\"><p>L'ulcère variqueux, également appelé <span class=\"nc-red nc-bold\">ulcère veineux</span>, est le <strong>plus fréquent</strong> des ulcères de jambe, représentant environ <strong>80 %</strong> des cas.</p></div>"},{"i":"2e9129fcab8f","n":227,"o":"227-9","u":"Diagnostic positif","t":"Connaître les méthodes diagnostiques de l’IVC","q":"Les manœuvres cliniques spécifiques (signe du flot, signe de Schwartz, épreuve de Trendelenburg) sont-elles à connaître pour le diagnostic d'insuffisance veineuse chronique dans le cadre de l'EDN français ?","a":"<div class=\"notion-course\"><p>Non, les manœuvres cliniques spécifiques telles que le signe du flot, le signe de <span class=\"nc-yellow_bg\">Schwartz</span> et l'épreuve de <span class=\"nc-yellow_bg\">Trendelenburg</span> sont <strong>hors programme</strong> pour l'EDN français.</p></div>"},{"i":"b2d866122902","n":227,"o":"227-9","u":"Diagnostic positif","t":"Connaître les méthodes diagnostiques de l’IVC","q":"Quelles sont les indications de l'échographie-Doppler veineuse des membres inférieurs dans le contexte de l'insuffisance veineuse chronique (IVC) ?","a":"<div class=\"notion-course\"><ul><li>Confirmer le diagnostic d'IVC.</li><li>Bilan pré-opératoire (systématique avant chirurgie variqueuse).</li><li>Bilan pré-sclérose : cartographie veineuse et mesure du diamètre des varices.</li><li>Bilan d'un ulcère des <span class=\"nc-green nc-bold\">membres inférieurs</span>.</li><li>Suspicion de thrombose veineuse profonde (TVP).</li></ul></div>"},{"i":"ffb0fcb5007f","n":227,"o":"227-9","u":"Diagnostic positif","t":"Connaître les méthodes diagnostiques de l’IVC","q":"Quel est l'examen de référence pour le diagnostic de l'insuffisance veineuse chronique (IVC) et dans quelle position doit-il être réalisé ?","a":"<div class=\"notion-course\"><p>L'examen de référence pour le diagnostic de l'insuffisance veineuse chronique (IVC) est l'<strong>échographie-Doppler veineuse des <span class=\"nc-green nc-bold\">membres inférieurs</span></strong>. Il doit être réalisé en <strong>position debout</strong>.</p></div>"},{"i":"576777b95215","n":227,"o":"227-2","u":"Physiopathologie","t":"Connaître les principaux mécanismes physiopathologiques responsables de l’IVC","q":"Quels sont les points clés concernant les principaux mécanismes physiopathologiques responsables de l’IVC ?","a":"<div class=\"notion-course\"><ul><li>Le <span>retour veineux</span> s'effectue contre la <span>pression orthostatique</span> (<span>pesanteur</span>), grâce à la synergie de plusieurs acteurs :</li><li>Les valvules orientent le retour veineux et limitent le <span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">reflux</span></span> ; leur distribution varie selon les segments veineux.</li><li><strong>Pompe musculaire du <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">mollet</span></span></strong> (acteur majeur) : à la <strong>contraction</strong>, le muscle comprime le réseau <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">profond</span></span> contenu dans une <span>aponévrose inextensible</span> et propulse le flux vers le haut ; au <strong>relâchement</strong>, le sang du réseau <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">superficiel</span></span> est aspiré vers le réseau <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">profond</span></span>.</li><li><strong><span><span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">Pression dynamique résiduelle</span></span></span></strong> : issue de l'éjection du ventricule gauche transmise jusqu'au versant veineux.</li></ul></div>"},{"i":"10d89b317541","n":227,"o":"227-4","u":"Étiologies","t":"Connaître les étiologies des varices et de l’IVC","q":"Quels sont les points clés concernant les étiologies des varices et de l’IVC ?","a":"<div class=\"notion-course\"><ul><li>Les étiologies des varices et de l'IVC se répartissent en trois grandes familles :</li><li><em>📎 Items liés : 226 — <span>Thrombose veineuse profonde</span> - EP</em></li></ul></div>"},{"i":"8098fa2ed81c","n":227,"o":"227-6","u":"Epidémiologie","t":"Connaître la prévalence de l’IVC","q":"Quels sont les points clés concernant la prévalence de l’IVC ?","a":"<div class=\"notion-course\"><ul><li>L'IVC est un véritable <strong><span>problème de santé publique</span></strong> :</li><li><span>Prévalence</span> globale d'environ <span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\">30 à 60 %</span></span></span> dans les pays industrialisés.</li><li>Environ <span>20 millions</span> d'IVC et plus de <span>400 000</span> ulcères d'origine veineuse.</li><li>Nette <strong>prédominance <span class=\"nc-pink_bg\"><span class=\"nc-pink_bg\">féminine</span></span></strong> (<span>3 femmes pour 1 homme</span>), qui tend à s'équilibrer avec l'âge.</li></ul></div>"},{"i":"521ecf333407","n":227,"o":"227-10","u":"Prise en charge","t":"Connaître les principes de prise en charge thérapeutiques de l’IVC","q":"Quels sont les points clés concernant les principes de prise en charge thérapeutiques de l’IVC ?","a":"<div class=\"notion-course\"><ul><li><strong>1. Mesures générales et hygiène de vie</strong> — socle du traitement :</li><li>Surélévation des jambes et des pieds de <span>7 à 10 cm</span> au-dessus du lit.</li><li>Lutte contre le <span><span class=\"nc-brown_bg\"><span class=\"nc-brown_bg\">surpoids</span></span></span> et la <span><span class=\"nc-brown_bg\"><span class=\"nc-brown_bg\">sédentarité</span></span></span> (<span><span class=\"nc-green_bg\"><span class=\"nc-green_bg\">marche régulière quotidienne</span></span></span>).</li><li>Éviter de croiser les jambes en position assise et les stations debout immobiles prolongées.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181a7a796dac0b4603e0c?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Présentation aiguë ou chronique ?","detail":"<ul><li>Douleur brutale, œdème unilatéral ou cordon inflammatoire ?</li></ul>","branches":[{"label":"Aiguë","to":"thrombose"},{"label":"Chronique","to":"examen"}]},{"id":"thrombose","kind":"urgent","label":"Rechercher TVP/TVS et autres urgences","detail":"<ul><li>Ne pas attribuer une grosse jambe aiguë aux seules varices.</li></ul>","branches":[]},{"id":"examen","kind":"decision","label":"Varices, œdème, troubles trophiques ou ulcère ?","detail":"<ul><li>Inspection debout, pouls, contexte post-thrombotique et mécanisme.</li></ul>","branches":[{"label":"Ulcère","to":"ulcere"},{"label":"Autre maladie veineuse","to":"doppler"}]},{"id":"ulcere","kind":"decision","label":"Évaluer mécanisme veineux et artériel","detail":"<ul><li>IPS/pressions distales ; soins de plaie et parcours ulcère.</li></ul>","branches":[{"label":"Cartographie","to":"doppler"}]},{"id":"doppler","kind":"decision","label":"Reflux, obstruction ou dysfonction de pompe ?","detail":"<ul><li>Cartographie avant traitement invasif ; respecter les collatérales utiles.</li></ul>","branches":[{"label":"Traitement conservateur","to":"conservateur"},{"label":"Geste indiqué","to":"geste"}]},{"id":"conservateur","kind":"finish","label":"Marche, mesures adaptées et compression","detail":"<ul><li>Choix selon symptômes, perfusion, capacité d’enfilage et tolérance.</li></ul>","branches":[]},{"id":"geste","kind":"finish","label":"Traiter le reflux selon anatomie et bénéfice","detail":"<ul><li>Thermique, sclérothérapie ou chirurgie ; suivi et prévention de récidive.</li></ul>","branches":[]}]}};
